<?php

namespace App\Services;

use Carbon\Carbon;
use Illuminate\Support\Facades\Log;
use mysql_xdevapi\Exception;
use PhpOffice\PhpSpreadsheet\Reader\Ods;

class OdsService
{

    protected $user_name = 'VS_BAZK'; //ods 用户名

    protected $pass_word = 'vs_bazk#123'; //ods 密码

    protected $ods_ip = '10.32.82.8:1521/ods'; //ods 链接地址

    protected $character = 'UTF8'; //ods 编码

    private static $service;

    private $connect;

    private $sql;

    public function __construct()
    {
        try {
            if (!($this->connect = oci_connect($this->user_name, $this->pass_word, $this->ods_ip, $this->character))) {
                Log::info(__CLASS__.'链接ODS数据库报错::', ['msg' => htmlentities(data_get(oci_error(), 'message'))]);
            }
        }catch (\Exception $exception) {
            Log::info(__CLASS__.'链接ODS数据库报错::'.$exception->getMessage());
        }
    }

    /**
     * 获取当前类实例
     * @return OdsService
     */
    public static function getService() : self
    {
        //判断实例是否属于当前类
        if(!self::$service instanceof OdsService){
            self::$service = new OdsService();
        }
        return self::$service;
    }

    /**
     * 获取需要同步的数据
     * @param int $hours
     * @param false $start
     * @return $this
     */
    public function getSyncData($hours = 1, $start = false) : self
    {
        $start = Carbon::parse($start ?: null)->subHours($hours)->format("Y-m-d 00:00:00");
        $this->sql = "SELECT NVL(HIS.CI_MR_FP_PAT.ID_ENT, '') AS ZYH_ID, NVL( CASE WHEN HIS.CI_MR_FP_PAT_CATA.ID_ENT IS NULL THEN 2 ELSE 1 END,'') AS IS_CATA FROM HIS.CI_MR_FP_PAT LEFT JOIN HIS.EN_ENT ON HIS.EN_ENT.ID_ENT = HIS.CI_MR_FP_PAT.ID_ENT LEFT JOIN HIS.CI_MR_FP_OTHER ON HIS.CI_MR_FP_OTHER.ID_ENT= HIS.CI_MR_FP_PAT.ID_ENT LEFT JOIN HIS.CI_MR_FP_BL ON HIS.CI_MR_FP_OTHER.ID_ENT= HIS.CI_MR_FP_BL.ID_ENT LEFT JOIN HIS.EN_ENT_IP ON HIS.EN_ENT_IP.ID_ENT = HIS.CI_MR_FP_PAT.ID_ENT LEFT JOIN HIS.CI_MR_FP_PAT_CATA ON HIS.CI_MR_FP_PAT_CATA.ID_ENT = HIS.CI_MR_FP_PAT.ID_ENT WHERE (HIS.EN_ENT_IP.SD_STATUS = '25' OR HIS.EN_ENT_IP.SD_STATUS = '28') AND HIS.CI_MR_FP_PAT.\"ods_update_time\" >= TO_DATE('{$start}','yyyy-mm-dd hh24:mi:ss') ORDER BY HIS.CI_MR_FP_PAT.\"ods_update_time\" ASC ";
        return $this;
    }

    /**
