    {
        $this->sql = "SELECT NVL(HIS.CI_MR_FP_PAT_CATA.ID_ORG, '') AS hospital_name, NVL(HIS.CI_MR_FP_PAT_CATA.CODE_AMR_IP, '') AS AAA28, NVL(HIS.CI_MR_FP_PAT_CATA.ID_ENT, '') AS ZYH_ID, (NVL(HIS.CI_MR_FP_PAT_CATA.CODE_AMR_IP, '') || '' || NVL(HIS.CI_MR_FP_PAT_CATA.N_TIMES_INHOSPITAL, '')) AS MED_REC_ID, NVL(HIS.CI_MR_FP_PAT_CATA.NAME_PAT, '') AS AAA01, NVL(CASE WHEN HIS.CI_MR_FP_PAT_CATA.ID_SEX = '@@@@Z81000000003NSBP' THEN 0 WHEN HIS.CI_MR_FP_PAT_CATA.ID_SEX = '@@@@Z81000000003NSBQ' THEN 1 WHEN HIS.CI_MR_FP_PAT_CATA.ID_SEX = '@@@@Z81000000003NSBR' THEN 2 WHEN HIS.CI_MR_FP_PAT_CATA.ID_SEX = '' THEN 9 END, '') AS AAA02C, NVL(HIS.CI_MR_FP_PAT_CATA.NAME_SEX, '') AS AAA02C_MC, NVL(EN_ENT.DT_BIRTH_PAT, '') AS AAA03, NVL(HIS.CI_MR_FP_PAT_CATA.AGE, '') AS AAA04_1, NVL(CASE WHEN HIS.CI_MR_FP_PAT_CATA.SD_COUNTRY = '156' THEN 1 WHEN HIS.CI_MR_FP_PAT_CATA.SD_COUNTRY = 'CHN' THEN 1 ELSE 2 END, '') AS AAA05C, NVL(HIS.CI_MR_FP_PAT_CATA.NAME_COUNTRY, '') AS AAA05C_MC, NVL(HIS.CI_MR_FP_PAT_CATA.ADDMISSION_WEIGHT, '') AS AAA42, NVL(HIS.CI_MR_FP_PAT_CATA.BIRTH_WEIGHT, '') AS AEN01, NVL(HIS.CI_MR_FP_PAT_CATA.BIRTH_WEIGHT_ONE, '') AS AEN01_2, NVL(HIS.CI_MR_FP_PAT_CATA.BIRTH_WEIGHT_TWO, '') AS AEN01_3, NVL(HIS.CI_MR_FP_PAT_CATA.BIRTH_WEIGHT_THREE, '') AS AEN01_4, NVL(HIS.CI_MR_FP_PAT_CATA.BIRTH_WEIGHT_FOUR, '') AS AEN01_5, NVL(CASE WHEN HIS.CI_MR_FP_PAT_CATA.SD_NATION = '01' THEN 1 WHEN HIS.CI_MR_FP_PAT_CATA.SD_NATION = '02' THEN 2 WHEN HIS.CI_MR_FP_PAT_CATA.SD_NATION = '03' THEN 3 WHEN HIS.CI_MR_FP_PAT_CATA.SD_NATION = '05' THEN 5 WHEN HIS.CI_MR_FP_PAT_CATA.SD_NATION = '11' THEN 11 WHEN HIS.CI_MR_FP_PAT_CATA.SD_NATION = '97' THEN 66 END, '') AS AAA06C, NVL(HIS.CI_MR_FP_PAT_CATA.NAME_NATION, '') AS AAA06C_MC, NVL(HIS.CI_MR_FP_PAT_CATA.ID_CODE, '') AS AAA07, NVL(HIS.CI_MR_FP_PAT_CATA.SD_MARRY, '') AS AAA08C, NVL(HIS.CI_MR_FP_PAT_CATA.NAME_MARRY, '') AS AAA08C_MC, NVL(CI_MR_FP_OTHER_CATA.OUT_HOS_MODE, '') AS AEM01C, NVL(CI_MR_FP_OTHER_CATA.NAME_OUT_HOS_MODE, '') AS AEM01C_MC, NVL(HIS.CI_MR_FP_PAT_CATA.DT_ACPT, '') AS AAB01, NVL(HIS.CI_MR_FP_PAT_CATA.DT_END, '') AS AAC01, NVL(HIS.CI_MR_FP_PAT_CATA.HOSDAYS, '') AS AAC04, NVL(CI_MR_FP_BL_CATA.AMOUNT, '') AS ADA01, NVL(CI_MR_FP_BL_CATA.CMS_SPAMOUNT, '') AS ADA0101, NVL(HIS.CI_MR_FP_PAT_CATA.N_TIMES_INHOSPITAL, '') AS AAA29, NVL(CASE WHEN HIS.CI_MR_FP_PAT_CATA.SD_REFERALSRC = '1' THEN 2 WHEN HIS.CI_MR_FP_PAT_CATA.SD_REFERALSRC = '2' THEN 1 WHEN HIS.CI_MR_FP_PAT_CATA.SD_REFERALSRC = '3' THEN 3 WHEN HIS.CI_MR_FP_PAT_CATA.SD_REFERALSRC = '9' THEN 9 END, '') AS AAB06C, NVL(HIS.CI_MR_FP_PAT_CATA.NAME_REFERALSRC, '') AS AAB06C_MC, NVL(CASE WHEN HIS.CI_MR_FP_PAT_CATA.SD_PAY_METHOD = '1.1' THEN 1 WHEN HIS.CI_MR_FP_PAT_CATA.SD_PAY_METHOD = '1.2' THEN 1 WHEN HIS.CI_MR_FP_PAT_CATA.SD_PAY_METHOD = '2.1' THEN 2 WHEN HIS.CI_MR_FP_PAT_CATA.SD_PAY_METHOD = '2.2' THEN 2 WHEN HIS.CI_MR_FP_PAT_CATA.SD_PAY_METHOD = '3.1' THEN 3 WHEN HIS.CI_MR_FP_PAT_CATA.SD_PAY_METHOD = '3.2' THEN 3 WHEN HIS.CI_MR_FP_PAT_CATA.SD_PAY_METHOD = '4' THEN 4 WHEN HIS.CI_MR_FP_PAT_CATA.SD_PAY_METHOD = '5' THEN 5 WHEN HIS.CI_MR_FP_PAT_CATA.SD_PAY_METHOD = '6' THEN 6 WHEN HIS.CI_MR_FP_PAT_CATA.SD_PAY_METHOD = '7' THEN 7 WHEN HIS.CI_MR_FP_PAT_CATA.SD_PAY_METHOD = '8' THEN 8 WHEN HIS.CI_MR_FP_PAT_CATA.SD_PAY_METHOD = '9' THEN 99 END, '') AS AAA26C, NVL(HIS.CI_MR_FP_PAT_CATA.NAME_PAY_METHOD, '') AS AAA26C_MC, NVL(CI_MR_FP_OTHER_CATA.NAME_IIOUTREASON, '') AS ABG01N, NVL(CI_MR_FP_OTHER_CATA.SD_IIOUTREASON, '') AS ABG01C, NVL(CASE WHEN HIS.CI_MR_FP_PAT_CATA.ID_ENT IS NULL THEN 2 ELSE 1 END , '') AS is_CATA , NVL(CASE WHEN HIS.EN_ENT_IP.SD_STATUS = '25' THEN 1 ELSE 2 END, '') AS in_hospital FROM HIS.CI_MR_FP_PAT_CATA LEFT JOIN HIS.EN_ENT ON HIS.EN_ENT.ID_ENT = HIS.CI_MR_FP_PAT_CATA.ID_ENT LEFT JOIN HIS.CI_MR_FP_OTHER_CATA ON HIS.CI_MR_FP_OTHER_CATA.ID_ENT= HIS.CI_MR_FP_PAT_CATA.ID_ENT LEFT JOIN HIS.CI_MR_FP_BL_CATA ON HIS.CI_MR_FP_OTHER_CATA.ID_ENT= HIS.CI_MR_FP_BL_CATA.ID_ENT LEFT JOIN HIS.EN_ENT_IP ON HIS.EN_ENT_IP.ID_ENT= HIS.CI_MR_FP_BL_CATA.ID_ENT";
        return $this;
