    /**
     * operation表sql
     * @return $this
     */
    public function getOperationSql()
    {
        $this->sql = " SELECT (NVL(HIS.CI_MR_FP_PAT_CATA.CODE_AMR_IP, '') || '' || NVL(HIS.CI_MR_FP_PAT_CATA.N_TIMES_INHOSPITAL, '')) AS AAA28, NVL(CI_MR_FP_SUG_CATA.ID_ENT, '') AS ZYH_ID, NVL(CI_MR_FP_SUG_CATA.SD_SUG, '') AS ICD9_ID1, NVL(CI_MR_FP_SUG_CATA.NAME_SUG, '') AS ICD9_NAME, NVL(CI_MR_FP_SUG_CATA.DT_START_SUG, '') AS OPE_DATE, NVL(CI_MR_FP_SUG_CATA.NAME_EMP_SUG, '') AS OPE_MAN_NAME, NVL(CI_MR_FP_SUG_CATA.SD_EMP_SUG, '') AS OPE_MAN_CODE, NVL(CI_MR_FP_SUG_CATA.SD_EMP_ASST1, '') AS FRIST_ASSISTANT_CODE, NVL(CI_MR_FP_SUG_CATA.NAME_EMP_ASST1, '') AS FRIST_ASSISTANT_NAME, NVL(CI_MR_FP_SUG_CATA.SD_EMP_ASST2, '') AS SECOND_ASSISTANT_CODE, NVL(CI_MR_FP_SUG_CATA.NAME_EMP_ASST2, '') AS SECOND_ASSISTANT_NAME, NVL(CI_MR_FP_SUG_CATA.SD_ANESTP, '') AS HOCUS_WAY_ID, NVL(CI_MR_FP_SUG_CATA.NAME_ANESTP, '') AS HOCUS_WAY_MC, NVL(CI_MR_FP_SUG_CATA.ID_INCICONDI, '') AS INCISION_GRADE_ID, NVL(CI_MR_FP_SUG_CATA.NAME_INCICONDI, '') AS INCISION_GRADE_MC, NVL(CI_MR_FP_SUG_CATA.SD_EMP_ANES, '') AS HOCUS_MAN_CODE, NVL(CI_MR_FP_SUG_CATA.NAME_EMP_ANES, '') AS HOCUS_MAN_NAME, NVL(CI_MR_FP_SUG_CATA.DT_START_SUG, '') AS START_TIME, NVL(CI_MR_FP_SUG_CATA.DT_END_SUG, '') AS END_TIME, NVL(CI_MR_FP_SUG_CATA.SORTNO, '') AS OPE_ORDER, NVL(CI_MR_FP_SUG_CATA.SD_LVLSUG, '') AS OPE_LEVEL, NVL(CI_MR_FP_SUG_CATA.NAME_LVLSUG, '') AS OPE_LEVEL_MC, NVL(CI_MR_FP_SUG_CATA.SD_CLASS_SUG, '') AS SSPB, NVL(CI_MR_FP_SUG_CATA.NAME_CLASS_SUG, '') AS SSPB_MC, NVL(CI_MR_FP_SUG_CATA.SORTNO, '') AS SFZYSS, NVL(CI_MR_FP_SUG_CATA.SD_INCITP, '') AS QKDJ, NVL(CI_MR_FP_SUG_CATA.NAME_INCITP, '') AS QKDJ_MC, NVL(CI_MR_FP_SUG_CATA.SD_METHOD_SUG, '') AS SSLX, NVL(CI_MR_FP_SUG_CATA.NAME_METHOD_SUG, '') AS SSLX_MC,NVL ( CI_MR_FP_SUG_CATA.ID_MRFPSUG, '' ) AS SSXH FROM HIS.CI_MR_FP_PAT_CATA LEFT JOIN HIS.CI_MR_FP_SUG_CATA ON HIS.CI_MR_FP_SUG_CATA.ID_ENT = HIS.CI_MR_FP_PAT_CATA.ID_ENT";
        return $this;
    }

    /**
     * feeDetailed表sql
     * @return $this
     */
    public function getFeeDetailedSql()
    {
        $this->sql = "SELECT NVL(BL_CG_IP.ID_CGIP, '') AS FYXH, NVL(BL_CG_IP.NAME_SRV, '') AS FYMC, NVL(BL_CG_IP.DT_ST, '') AS JFRQ, NVL(BL_CG_IP.QUAN, '') AS FYSL, NVL(BL_CG_IP.AMT_STD, '') AS FYDJ, NVL(BL_CG_IP.ID_DEP_OR, '') AS FYKS, NVL(BL_CG_IP.NAME_INCCAITM, '') AS FYGB, NVL(BL_CG_IP.ID_CGIP, '') AS JLXH, NVL(BL_CG_IP.ID_DEP_MP, '') AS ZXKS, NVL(BL_CG_IP.CODE_HPPR, '') AS YBBM, NVL(BL_CG_IP.FG_REFUND, '') AS TKBZ, NVL(BL_CG_IP.NAME_ACCOUNT, '') AS SYGB,(NVL ( BL_CG_IP.ID_CGIP, '' ) || '' || NVL (to_char (BL_CG_IP.\"ods_insert_time\", 'yyyymmddHH24miss'),'')) AS FYXH_NO FROM HIS.BL_CG_IP LEFT JOIN HIS.CI_MR_FP_PAT_CATA ON HIS.BL_CG_IP.ID_ENT = HIS.CI_MR_FP_PAT_CATA.ID_ENT ";
        return $this;
    }

    /**
     * yzb表sql
     * @return $this
     */
    public function getYzSql()
    {
        $this->sql =  "SELECT (NVL(CI_MR_FP_PAT_CATA.CODE_AMR_IP, '') || '' || NVL(CI_MR_FP_PAT_CATA.N_TIMES_INHOSPITAL, '')) AS ZYH, NVL(CI_ORDER.ID_EN, '') AS ZYH_ID, NVL(CI_ORDER.ID_OR, '') AS YZBXH, NVL(CI_ORDER.ID_DEP_OR, '') AS BRKS, NVL(CI_ORDER.ID_WG_OR, '') AS BRBQ, NVL(CI_ORDER.SD_SRVTP, '') AS YDYZLB, NVL(CASE CI_ORDER.FG_LONG WHEN 'Y' THEN 1 WHEN 'N' THEN 2 ELSE 3 END, '') AS YZQX, NVL(CI_ORDER.ID_DEP_OR, '') AS KZKS, NVL(CI_ORDER.ID_EMP_OR, '') AS KZYS, NVL(CI_ORDER.DT_ENTRY, '') AS KZSJ, NVL(CI_ORDER.NAME_OR, '') AS YZMC, NVL(CI_ORDER.ID_FREQ, '') AS YPCD, NVL(CI_ORDER.ID_FREQ, '') AS SYPC, NVL(CI_ORDER.ID_ROUTE, '') AS GYTJ, NVL(CI_ORDER.ID_ROUTE, '') AS YCJL, NVL(CASE CI_ORDER.FG_URGENT WHEN 'Y' THEN 1 WHEN 'N' THEN 0 ELSE 9 END, '') AS JJYZ, NVL(CI_ORDER.SD_SU_OR, '') AS YZZT, NVL(CI_ORDER.SD_SU_MP, '') AS ZXZT, NVL(CI_ORDER.ID_EMP_CHK, '') AS XZJDGH, NVL(CI_ORDER.DT_CHK, '') AS XZJDSJ, NVL( CASE CI_ORDER.FG_SKINTEST WHEN 'Y' THEN 1 WHEN 'N' THEN 0 ELSE 9 END, '' ) AS PSBZ,NVL( CASE CI_ORDER.FG_CANC WHEN 'Y' THEN 1 WHEN 'N' THEN 0 ELSE 9 END, '' ) AS ZFBS FROM HIS.CI_ORDER LEFT JOIN HIS.CI_MR_FP_PAT_CATA ON HIS.CI_ORDER.ID_EN = HIS.CI_MR_FP_PAT_CATA.ID_ENT ";
        return $this;
    }

    /**
     * 获取所属院区
     * @param $ksCode
     * @return $this
     */
    public function getYq($ksCode)
    {
        $this->sql =  "SELECT NVL(BD_UDIDOC.ID_UDIDOC, '') AS YQ_CODE FROM HIS.BD_UDIDOC  WHERE HIS.BD_UDIDOC.ID_UDIDOCLIST = '@@@@LL200000000002GJ' AND HIS.BD_UDIDOC.CODE = （SELECT NVL(BD_DEP.SD_HOSDISTRICT, '') AS SD_HOSDISTRICT FROM HIS.BD_DEP WHERE HIS.BD_DEP.CODE = {$ksCode}";
        return $this;
    }

    public function setCommonWhere($ID_ENT){
        $this->sql .= " WHERE HIS.CI_MR_FP_PAT_CATA.ID_ENT = {$ID_ENT}";
        return $this;
    }

    public function getResult()
    {
        $result = [];
        try {
            $data = oci_parse($this->connect, $this->sql);

            oci_execute($data, OCI_DEFAULT);

            while ($row = oci_fetch_assoc($data)) {
                $result[] = $row;
            }
            oci_free_statement($data);

        }catch (\Exception $exception){
            Log::error(__CLASS__."ODS查询失败,请检查链接或查询语句::".$exception->getMessage());
        }

        return $result;
    }
}
